    links=json.loads(LINKS.read_text(encoding="utf-8")); tasks=json.loads(TASKS.read_text(encoding="utf-8")); artifacts=[row for row in links["artifacts"] if "strongest_candidates" in row["categories"]]; task_by_id={row["subject_id"]:row for row in tasks["tasks"] if row["task_type"]=="CANDIDATE_REVIEW"}; rows=[]
    for artifact in sorted(artifacts,key=lambda row:Path(row["path"]).name.split("-")[0]):
        name=Path(artifact["path"]).name; match=re.match(r"(?P<candidate>[ch]\d{3})-(?P<panel>p\d{3})-(?P<style>.+)-r1\.png$",name); candidate=match.group("candidate") if match else ""; task=task_by_id.get(candidate)
        if not match or not task or task["artifact"]["sha256"]!=artifact["sha256"]: raise SystemExit(f"candidate/task mismatch: {name}")
        path=ROOT/artifact["path"]; rows.append({"candidate_id":candidate,"panel_id":match.group("panel").upper(),"style":match.group("style"),"artifact":bind(path),"checks":{key:None for key in CHECKS},"disposition":None,"targeted_repair_class":None,"reviewer":None,"human_review_minutes":None,"notes":None})
