    guide=["# CH05 strongest-candidate disposition guide r1","","Open each linked candidate and fill all eight checks with `PASS`, `WARN`, or `FAIL`. Then choose one visual disposition. Use `REQUEST_ONE_TARGETED_REPAIR` only with one repair class.","","`ADVANCE_TO_NEXT_COMPARISON` means keep comparing; it is not candidate acceptance, commercial clearance, or exact-base selection.",""]+[f"- [{row['candidate_id']} · {row['panel_id']} · {row['style']}]({row['artifact']['absolute_path']})" for row in rows]; GUIDE.write_text("\n".join(guide)+"\n",encoding="utf-8",newline="\n"); evidence={"record_type":"CH05StrongestCandidateDispositionWorksheetEvidence","schema_version":"1.0","record_id":"ng-ch05-strongest-candidate-disposition-worksheet-evidence-r1","state":"PASS_NULL_TEMPLATE","worksheet":{"path":OUTPUT.relative_to(ROOT).as_posix(),"sha256":sha(OUTPUT)},"guide":{"path":GUIDE.relative_to(ROOT).as_posix(),"sha256":sha(GUIDE)},"inputs":worksheet["inputs"],"summary":{"candidates":14,"checks_per_candidate":8,"total_checks":112,"filled_checks":0,"dispositions":0,"targeted_repairs":0,"reviewers":0,"human_review_minutes":None,"shortlist_rollup":0,"route_decisions":0,"candidate_acceptance":0,"commercial_clearance":0,"exact_base_selection":0,"plan_revisions":0},"animation_shot_plan":None,"e_conte":None}; EVIDENCE.parent.mkdir(parents=True,exist_ok=True); EVIDENCE.write_text(json.dumps(evidence,indent=2)+"\n",encoding="utf-8",newline="\n"); print("CH05 candidate worksheet: 14 candidates/112 null checks/0 dispositions; acceptance/rights/exact-base 0"); return 0
